source:
source note sys.dataset(fields: [title, summary, as_of, subtitle, status, metric1_label, metric1_value, metric2_label, metric2_value])

copy app { class: vocabulary, en: "Mail" }
copy gist { class: model-copy, en: "Simulation only. Nothing is reserved until you confirm with the clinic." }
copy action { class: model-copy, en: "Next: reply to the clinic if that time works for you." }

view root Surface(pad: .tight) {
  Col(gap: 6) {
    Row(gap: 6, align: .center) {
      Icon(name: .mail, size: .row)
      TextCaption(text: copy.app, width: .fill)
      TextCaption(text: "Simulation")
      TextCaption(value: note.status)
    }
    TextTitle(text: note.title, width: .fill)
    TextBody(text: note.subtitle, width: .fill)
    Row(gap: 8, align: .center) {
      TextCaption(value: note.metric1_label)
      TextBody(text: note.metric1_value, width: .fill)
    }
    Row(gap: 8, align: .center) {
      TextCaption(value: note.metric2_label)
      TextBody(text: note.metric2_value, width: .fill)
    }
    TextCaption(text: copy.action, width: .fill)
  }
}
